import {svg,bounds,scale,axes,series,palette,text,ticksLabel,esc} from '../gallery-utils.js';
export function render({data,params:p}){const b=bounds(p);b.r=p.width-100;const colors=palette(p),x=scale(data.map(d=>d.x),b.l,b.r),y=scale(data.map(d=>d.left),b.b,b.t),z=scale(data.map(d=>d.right),b.b,b.t),rows=[...data].sort((a,b)=>a.x-b.x);let s=axes(b,x,y,p)+series(rows.map(d=>({x:d.x,y:d.left})),x,y,colors[0],p)+series(rows.map(d=>({x:d.x,y:d.right})),x,z,colors[1],p)+`<path d="M${b.r},${b.t}V${b.b}" stroke="${colors[1]}"/>`;for(const v of z.ticks)s+=text(b.r+8,z(v)+4,ticksLabel(v),`fill="${colors[1]}"`);s+=`<text transform="translate(${p.width-20} ${(b.t+b.b)/2}) rotate(90)" text-anchor="middle" fill="${colors[1]}">${esc(p.rightLabel)}</text>`;s+=text(b.l+10,b.t+15,'左：'+p.yLabel,`fill="${colors[0]}"`)+text(b.l+10,b.t+36,'右：'+p.rightLabel,`fill="${colors[1]}"`);return svg(p,s);}